  "If access was denied earlier, open": { pl: "Jeśli wcześniej odmówiono dostępu, otwórz", de: "Falls der Zugriff zuvor verweigert wurde, öffne", es: "Si antes denegaste el acceso, abre", fr: "Si l’accès a été refusé, ouvrez" },
  ", enable MixBar, and relaunch it.": { pl: ", włącz MixBar i uruchom go ponownie.", de: ", aktiviere MixBar und starte es neu.", es: ", activa MixBar y vuelve a abrirlo.", fr: ", activez MixBar et relancez-le." },
  "3. Choose your audio output": { pl: "3. Wybierz wyjście audio", de: "3. Audioausgang auswählen", es: "3. Elige la salida de audio", fr: "3. Choisissez votre sortie audio" },
