  "Safari setup is built into MixBar: enable": { pl: "Konfiguracja Safari jest wbudowana w MixBar: włącz", de: "Die Safari-Einrichtung ist in MixBar integriert: Aktiviere", es: "La configuración de Safari está integrada en MixBar: activa", fr: "La configuration de Safari est intégrée à MixBar : activez" },
