  "Bundled Safari extension": { pl: "Dołączone rozszerzenie Safari", de: "Enthaltene Safari-Erweiterung", es: "Extensión de Safari incluida", fr: "Extension Safari incluse" },
  "Free MixBar companion extension": { pl: "Bezpłatne rozszerzenie towarzyszące MixBar", de: "Kostenlose MixBar-Begleiterweiterung", es: "Extensión complementaria gratuita de MixBar", fr: "Extension compagnon MixBar gratuite" },
  "Not available": { pl: "Niedostępne", de: "Nicht verfügbar", es: "No disponible", fr: "Non disponible" },
  "Firefox app-level control": { pl: "Sterowanie Firefoksem na poziomie aplikacji", de: "Firefox-Steuerung auf App-Ebene", es: "Control de Firefox a nivel de app", fr: "Contrôle de Firefox au niveau de l’app" },
  "Safari tab control works with standard HTML audio and video. Web Audio-only, protected, and some embedded players remain controllable through Safari’s app-level slider.": { pl: "Sterowanie kartami Safari działa ze standardowym dźwiękiem i wideo HTML. Odtwarzacze Web Audio, chronione treści i niektóre osadzone odtwarzacze pozostają dostępne przez suwak całej aplikacji Safari.", de: "Die Safari-Tabsteuerung funktioniert mit normalem HTML-Audio und -Video. Reine Web-Audio-, geschützte und manche eingebettete Player bleiben über den App-Regler von Safari steuerbar.", es: "El control de pestañas de Safari funciona con audio y vídeo HTML estándar. Web Audio, el contenido protegido y algunos reproductores incrustados siguen controlándose con el volumen general de Safari.", fr: "Le contrôle des onglets Safari fonctionne avec l’audio et la vidéo HTML standard. Web Audio, les contenus protégés et certains lecteurs intégrés restent contrôlables via le curseur général de Safari." },
  "Private by design": { pl: "Prywatność od podstaw", de: "Privat von Grund auf", es: "Privado por diseño", fr: "Privé par conception" },
  "Your audio stays yours.": { pl: "Twój dźwięk pozostaje tylko Twój.", de: "Dein Audio bleibt deins.", es: "Tu audio sigue siendo tuyo.", fr: "Votre son reste le vôtre." },
  "Local processing": { pl: "Przetwarzanie lokalne", de: "Lokale Verarbeitung", es: "Procesamiento local", fr: "Traitement local" },
  "No recordings": { pl: "Bez nagrań", de: "Keine Aufnahmen", es: "Sin grabaciones", fr: "Aucun enregistrement" },
  "No tracking SDKs": { pl: "Bez bibliotek śledzących", de: "Keine Tracking-SDKs", es: "Sin SDK de seguimiento", fr: "Aucun SDK de suivi" },
  "Set up in minutes": { pl: "Konfiguracja w kilka minut", de: "In Minuten eingerichtet", es: "Configúralo en minutos", fr: "Configuré en quelques minutes" },
  "Install it. Grant access. Take control.": { pl: "Zainstaluj. Udziel dostępu. Przejmij kontrolę.", de: "Installieren. Zugriff erlauben. Kontrolle übernehmen.", es: "Instala. Da acceso. Toma el control.", fr: "Installez. Autorisez. Prenez le contrôle." },
  "Drag to Applications": { pl: "Przeciągnij do Aplikacji", de: "In Programme ziehen", es: "Arrastra a Aplicaciones", fr: "Glissez dans Applications" },
  "Open the MixBar disk image and move the app into your Applications folder.": { pl: "Otwórz obraz dysku MixBar i przenieś aplikację do folderu Aplikacje.", de: "Öffne das MixBar-Image und verschiebe die App in den Programme-Ordner.", es: "Abre la imagen de disco de MixBar y mueve la app a Aplicaciones.", fr: "Ouvrez l’image disque MixBar et placez l’app dans Applications." },
  "Enable System Audio": { pl: "Włącz dźwięk systemowy", de: "Systemaudio aktivieren", es: "Activa el audio del sistema", fr: "Activez l’audio système" },
  "macOS asks once so MixBar can adjust each application’s outgoing sound.": { pl: "macOS zapyta raz, aby MixBar mógł regulować dźwięk wyjściowy każdej aplikacji.", de: "macOS fragt einmal, damit MixBar den ausgehenden Ton jeder App regeln kann.", es: "macOS pregunta una vez para que MixBar pueda ajustar el sonido de salida de cada app.", fr: "macOS demande une fois l’autorisation pour que MixBar règle le son sortant de chaque app." },
  "Move a slider": { pl: "Przesuń suwak", de: "Regler bewegen", es: "Mueve un control", fr: "Déplacez un curseur" },
  "Every app producing audio appears automatically. Browser tab setup is optional.": { pl: "Każda aplikacja odtwarzająca dźwięk pojawia się automatycznie. Konfiguracja kart przeglądarki jest opcjonalna.", de: "Jede App mit Audio erscheint automatisch. Die Einrichtung von Browser-Tabs ist optional.", es: "Cada app que produce audio aparece automáticamente. Configurar pestañas es opcional.", fr: "Chaque app qui émet du son apparaît automatiquement. La configuration des onglets est facultative." },
  "Simple software. Simple price.": { pl: "Prosta aplikacja. Prosta cena.", de: "Einfache Software. Einfacher Preis.", es: "Software sencilla. Precio sencillo.", fr: "Un logiciel simple. Un prix simple." },
  "Per-app volume and mute": { pl: "Głośność i wyciszenie każdej aplikacji", de: "Lautstärke und Stummschaltung pro App", es: "Volumen y silencio por app", fr: "Volume et sourdine par app" },
  "Per-app, subprocess, and Chromium-tab EQ": { pl: "Korektor aplikacji, podprocesów i kart Chromium", de: "EQ pro App, Unterprozess und Chromium-Tab", es: "EQ por app, subproceso y pestaña Chromium", fr: "Égaliseur par app, sous-processus et onglet Chromium" },
  "Safari, Chrome, and Opera tab controls": { pl: "Sterowanie kartami Safari, Chrome i Opery", de: "Steuerung für Safari-, Chrome- und Opera-Tabs", es: "Control de pestañas de Safari, Chrome y Opera", fr: "Contrôle des onglets Safari, Chrome et Opera" },
